-- Summarizer: replace raw matches with short action labels, generated by
-- the macOS on-device `fm` CLI (Apple Foundation Models, fully local).
--
-- Only the displayed title changes: the item's id — what the plugin types
-- at the prompt and what the recall cache re-serves — always stays the
-- full command. Every failure path (fm missing, model busy, timeout,
-- refusal, malformed or duplicated labels) falls back to the raw elided
-- title, so replay never depends on or is blocked by the model.

local util = require('rex_replay.util')

-- The palette row is ~43 cells on Rex for Mac; the prompt states the limit
-- and the result is also enforced locally after parsing.
local DEFAULT_CHARS = 43
local DEFAULT_TIMEOUT = 10 -- hard cap on the fm wait; the picker must not
-- sit invisible behind a cosmetic feature (fallback is free: raw titles)
local DEFAULT_MAX_ITEMS = 24

local opts = {} -- set by configure()

local function configure(o)
  o = o or {}
  opts.enabled = o.enabled ~= false
  opts.cmd = o.cmd or { 'fm', 'respond' }
  opts.chars = o.chars or DEFAULT_CHARS
  opts.timeout = o.timeout or DEFAULT_TIMEOUT
  opts.max_items = o.max_items or DEFAULT_MAX_ITEMS
  opts._available = nil -- re-probe
  opts._fails = 0
end

local function instructions()
  return table.concat({
    'You label terminal commands for rows in a small user interface list.',
    'Reply with exactly one line per numbered item, formatted "N: label".',
    'Each label is a specific action phrase of at most seven words, shorter',
    'than ' .. opts.chars .. ' characters: a verb plus the identifying object',
    '(repository, branch, PR, file, host:port, package, image name).',
    'When an item shows terminal output in parentheses, use it to name what',
    'the command acts on: "remote: Create a pull request for BRANCH" calls',
    'for "open PR BRANCH", never "open link" or "view repository".',
    'Use only names that appear in the item itself; never reuse names from',
    'this instruction. Add no site names (no "on GitHub"), no quotes, no',
    'trailing period, no other text.',
  }, ' ')
end

local MAX_ID_CHARS = 200 -- ids are full commands; trim absurd ones from the prompt
local MAX_CTX_CHARS = 200 -- terminal line shown to the model as context

-- Only the first `count` items (the max_items window) go into the prompt;
-- numbering the whole 250-item tail would burn model context on labels
-- that get discarded at parse time. Each item carries the terminal line
-- it was found on (item.ctxline, set by extract_all): a bare URL is
-- ambiguous, its surrounding output usually names the action outright.
local function build_prompt(items, count)
  local lines = {}
  for i = 1, count do
    local line = i .. ': ' .. items[i].id:sub(1, MAX_ID_CHARS)
    local ctx = items[i].ctxline
    if ctx ~= nil and ctx ~= '' then
      line = line .. '\n   (seen in terminal output: ' .. ctx:sub(1, MAX_CTX_CHARS) .. ')'
    end
    lines[i] = line
  end
  return table.concat(lines, '\n')
end

-- Lua patterns have no alternation; check the list one by one.
local refusal_pats = {
  "i can'?t",
  'i cannot',
  'unable to',
  "i won'?t",
  'not able',
  'as an ai',
  "i'?m sorry",
  'i am sorry',
  "can'?t help",
  'cannot help',
  "i don'?t",
}

local function looks_like_refusal(s)
  s = s:lower()
  for _, pat in ipairs(refusal_pats) do
    if s:find(pat) then
      return true
    end
  end
  return false
end

-- Chat-style preambles the model sometimes emits before the real list;
-- never valid as an action label, and dangerous in the positional branch.
local preamble_pats = {
  '^sure',
  '^here you go',
  "^here'?s ",
  '^here is',
  '^here are',
  '^certainly',
  '^of course',
  '^no problem',
  '^below (are|is) ',
  '^following (are|is) ',
  "^i'?ll ",
  '^okay$',
  '^ok$',
  '^absolutely',
}

local function looks_like_preamble(line)
  local s = line:lower()
  for _, pat in ipairs(preamble_pats) do
    if s:find(pat) then
      return true
    end
  end
  return false
end

-- Normalize one model-produced label; nil when unusable.
local function clean_label(line)
  if line == nil then
    return nil
  end
  local s = line:match('^%s*(.-)%s*$')
  if s == '' then
    return nil
  end
  s = s:gsub('^[%s"\']+', ''):gsub('[%s"\']+$', '') -- strip wrapping quotes
  s = s:gsub('%s*[%.$:!;]%s*$', '') -- trailing punctuation
  s = s:gsub('[\r\n\t]', ' ')
  s = s:gsub('%s+', ' ')
  if s == '' then
    return nil
  end
  if looks_like_refusal(s) then
    return nil
  end
  if looks_like_preamble(s) then
    return nil
  end
  if s:find('://') or s:find('->') or s:find('<%a+>') then
    return nil -- echoed command/prompt line, or template bleed from an
    -- example; a real label never carries a URL, arrow, or <placeholder>
  end
  -- the small model bolts "on GitHub" onto nearly every label (~10 of 43
  -- cells of zero information, and it forces the entity to elide);
  -- deterministic strip, do not trust the instruction. No pattern
  -- alternation in Lua: one gsub per preposition.
  for _, prep in ipairs { 'on', 'to', 'in', 'for', 'at' } do
    s = s:gsub('%s%f[%w]' .. prep .. '%s+GitHub$', '')
  end
  s = s:gsub('%s%f[%w]GitHub$', '')
  s = s:match('^%s*(.-)%s*$')
  if #s < 3 then
    return nil -- nothing but the stripped suffix survived
  end
  if #s > opts.chars then
    s = util.elide_middle(s, opts.chars) -- model ignored the limit
  end
  return s
end

-- Parse "N: label" lines into a map index -> label. If too few lines are
-- numbered (models sometimes drop the numbers), fall back to positional.
local function parse_labels(text, count)
  local labels = {}
  if text == nil or text == '' then
    return labels
  end
  local lines = {}
  for line in (text .. '\n'):gmatch('([^\r\n]*)\n') do
    if line:match('%S') then
      lines[#lines + 1] = line
    end
  end
  local numbered = 0
  for _, line in ipairs(lines) do
    local n, rest = line:match('^%s*(%d+)%s*[:%.%)%]]?%s*(.+)$')
    if n and tonumber(n) >= 1 and tonumber(n) <= count and rest then
      numbered = numbered + 1
    end
  end
  if numbered >= math.ceil(#lines / 2) then
    for _, line in ipairs(lines) do
      local n, rest = line:match('^%s*(%d+)%s*[:%.%)%]]?%s*(.+)$')
      n = tonumber(n)
      if n and n >= 1 and n <= count and rest and labels[n] == nil then
        labels[n] = clean_label(rest)
      end
    end
  else
    -- Positional zip is only trustworthy when there is exactly one line
    -- per item and none of them is chat chatter: a preamble or dropped
    -- line would shift every label onto the wrong command, and a wrong
    -- summary is worse than a raw title (it misdescribes what gets
    -- typed). Anything else: keep all raw titles.
    if #lines == count then
      for _, line in ipairs(lines) do
        if looks_like_preamble(line) then
          return {}
        end
      end
      for i = 1, count do
        labels[i] = clean_label(lines[i]:match('^%s*%d+%s*[:%.%)%]]?%s*(.+)$') or lines[i])
      end
    end
  end
  return labels
end

local function fm_available()
  -- one cheap probe per config load; reset by configure()
  if opts._available == nil then
    local res = rex.exec({ opts.cmd[1], '--help' }, { timeout = 5, stdout = false, stderr = false })
    opts._available = res ~= nil and res.ok == true
    if not opts._available then
      util.log_info('summarizer: ' .. opts.cmd[1] .. ' not usable; titles stay raw')
    end
  end
  return opts._available
end

-- Replaces titles in-place with model summaries (batched into a single
-- fm call). Items beyond max_items and any item whose label is missing,
-- refused, or duplicated keep their raw elided title.
local function summarize(items)
  if not opts.enabled or #items < 2 or not fm_available() then
    -- a single item auto-types; its title is never shown
    return items
  end
  local count = math.min(#items, opts.max_items)
  local argv = {}
  for i = 1, #opts.cmd do
    argv[i] = opts.cmd[i]
  end
  -- pin the on-device model: `fm` otherwise honors its CLI config, and a
  -- user-configured pcc/provider would silently ship pane contents off-device
  argv[#argv + 1] = '--model'
  argv[#argv + 1] = 'system'
  argv[#argv + 1] = '--no-stream'
  argv[#argv + 1] = '-i'
  argv[#argv + 1] = instructions()
  argv[#argv + 1] = build_prompt(items, count)
  -- generation is output-bound (~0.5 s/label measured); the wait scales
  -- WITH the batch but is capped by the timeout option, so the picker
  -- always appears promptly — on cap the whole list keeps raw titles,
  -- which is a free fallback (labels are cosmetic; ids never change).
  -- A user who would rather wait longer for labels raises `timeout`.
  local budget = math.max(1, math.floor(math.min(opts.timeout, 4 + 0.5 * count)))
  util.log_info(string.format('summarizer: asking fm for %d labels (<= %ds)...', count, budget))
  local res, err = rex.exec(argv, { cwd = os.getenv('HOME') or '/tmp', timeout = budget })
  if res == nil or not res.ok then
    -- a missing program or a hard error is permanent for this config
    -- load; a timeout may be transient (the model can be busy), so it
    -- only counts toward the breaker instead of disabling summaries
    local why = err or (res and (res.timed_out and 'timeout' or 'exit ' .. tostring(res.code)) or 'error')
    util.log_info('summarizer: fm failed (' .. tostring(why) .. '); using raw titles')
    if res ~= nil and not res.timed_out then
      opts._fails = (opts._fails or 0) + 1
      if opts._fails >= 3 then
        opts._available = false
      end
    end
    return items
  end
  local labels = parse_labels(res.stdout, count)
  opts._fails = 0 -- consecutive-failure breaker, not lifetime

  -- the current titles ARE the raw elided commands; snapshot before any
  -- label overwrites one, so applied rows can show the command underneath
  local raws = {}
  for i = 1, count do
    raws[i] = items[i].title
  end

  -- duplicate summaries defeat the point of the list; drop them in favour
  -- of the unique elided raw titles
  local seen = {}
  for i = 1, count do
    local l = labels[i]
    if l then
      seen[l] = (seen[l] or 0) + 1
    end
  end
  local applied = 0
  for i = 1, count do
    local l = labels[i]
    if l and seen[l] == 1 then
      items[i].title = l
      -- subtitle carries the raw command under the label (quiet second
      -- line); unlabeled rows keep title=raw and NO subtitle, so nothing
      -- ever renders the same string twice
      items[i].subtitle = raws[i]
      applied = applied + 1
    end
  end
  util.log_info(string.format('summarizer: %d/%d labels from fm', applied, count))
  return items
end

-- Public entry: consume ctxline, then strip it — pick items and the recall
-- cache may carry only documented keys. All returns flow through here.
local function summarize_all(items)
  local out = summarize(items)
  for _, item in ipairs(out) do
    item.ctxline = nil
  end
  return out
end

return {
  configure = configure,
  summarize = summarize_all,
  -- internals for tests
  _opts = opts,
  _parse_labels = parse_labels,
  _clean_label = clean_label,
  _build_prompt = build_prompt,
}
